import (
	"encoding/json"
	"os"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPath 是阈值配置文件的位置，相对进程的工作目录。
// 它是变量而不是常量，测试才能指向自己的临时配置，不去碰仓库里的那一份。
var thresholdsPath = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 仓库在 config/thresholds.json 里配了自己的阈值就用它；没配、或者配置读不出来
// （文件不存在、内容不是 JSON 对象）就回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, err := loadThresholds()
	if err != nil {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取阈值配置。任何读取或解析错误都原样向上报，由调用方决定回退。
func loadThresholds() (map[string]int, error) {
	data, err := os.ReadFile(thresholdsPath)
	if err != nil {
		return nil, err
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, err
	}
	return thresholds, nil
}

