package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// pointThresholdsAt 把阈值配置指向一个临时文件，测试不碰仓库里的 config/thresholds.json。
// content 为空表示这个文件不存在。
func pointThresholdsAt(t *testing.T, content string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if content != "" {
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			t.Fatalf("写临时阈值配置失败：%v", err)
		}
	}
	old := thresholdsPath
	thresholdsPath = path
	t.Cleanup(func() { thresholdsPath = old })
}

func TestThresholdUsesConfiguredValue(t *testing.T) {
	pointThresholdsAt(t, `{"shanghai": 20}`)
	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(%q) = %d, 期望配置值 20", "shanghai", got)
	}
	if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置的仓库 LowStockThreshold(%q) = %d, 期望默认值 %d",
			"beijing", got, DefaultLowStockThreshold)
	}
}

func TestThresholdFallsBackWhenFileMissing(t *testing.T) {
	pointThresholdsAt(t, "")
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在时 LowStockThreshold(%q) = %d, 期望默认值 %d",
			"shanghai", got, DefaultLowStockThreshold)
	}
}

func TestThresholdFallsBackWhenUnreadable(t *testing.T) {
	old := thresholdsPath
	thresholdsPath = t.TempDir() // 目录不是文件，ReadFile 会失败
	t.Cleanup(func() { thresholdsPath = old })
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("读不出来时 LowStockThreshold(%q) = %d, 期望默认值 %d",
			"shanghai", got, DefaultLowStockThreshold)
	}
}

func TestThresholdFallsBackOnNonObjectContent(t *testing.T) {
	cases := map[string]string{
		"不是 JSON":  `not json`,
		"不是对象":   `[1, 2, 3]`,
		"值不是整数": `{"shanghai": "high"}`,
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			pointThresholdsAt(t, content)
			if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
				t.Fatalf("内容为 %s 时 LowStockThreshold(%q) = %d, 期望默认值 %d",
					name, "shanghai", got, DefaultLowStockThreshold)
			}
		})
	}
}

